===WORLD===
const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  //
  // localStorage snapshot: happy-dom gives each Window its own Storage, so a fresh Window on
  // reload would lose persisted todos and the persisted route. A real browser keeps
  // localStorage across a reload, so when a scenario reloads the app we snapshot the current
  // Storage and restore it into the new Window BEFORE the app's init reads it. This models
  // real reload semantics (fresh DOM and JS, durable localStorage) without faking the app.
  loadApp(localStorageSnapshot) {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    // disableCSSFileLoading: the template links CSS from node_modules via http://localhost/, which
    // would otherwise attempt a network fetch; the executable tier asserts structure and classes,
    // never computed styles, so CSS need not load.
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true, disableCSSFileLoading: true },
    });
    this.document = this.window.document;

    if (localStorageSnapshot) {
      for (const key of Object.keys(localStorageSnapshot)) {
        this.window.localStorage.setItem(key, localStorageSnapshot[key]);
      }
    }

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });
===STEPS===
const { Given, When, Then } = require('@cucumber/cucumber');

// ---- helpers ----------------------------------------------------------------

function todoLis(world) {
  return Array.prototype.slice.call(world.document.querySelectorAll('.todo-list li'));
}
function todoLi(world, title) {
  return todoLis(world).filter(function (li) {
    var label = li.querySelector('label');
    return label && label.textContent === title;
  })[0];
}
function storedTodos(window) {
  var raw = window.localStorage.getItem('todos-vanilla');
  if (!raw) return [];
  try { return JSON.parse(raw); } catch (e) { return []; }
}
function storedRecord(window, title) {
  return storedTodos(window).filter(function (t) { return t.title === title; })[0];
}
var seedSeq = 0;
function setStoredTodo(window, title, completed) {
  var arr = storedTodos(window);
  arr.push({ id: 'seed-' + (seedSeq++), title: title, completed: completed });
  window.localStorage.setItem('todos-vanilla', JSON.stringify(arr));
}

function addTodoViaUI(world, title) {
  var input = world.document.querySelector('.new-todo');
  input.value = title;
  var e = new world.window.KeyboardEvent('keydown', { bubbles: true, key: 'Enter' });
  input.dispatchEvent(e);
}
function checkTodoByTitle(world, title, checked) {
  var li = todoLi(world, title);
  if (!li) throw new Error('no todo with title "' + title + '"');
  var toggle = li.querySelector('.toggle');
  toggle.checked = checked;
  toggle.dispatchEvent(new world.window.Event('change', { bubbles: true }));
}
function enterEditing(world, title) {
  var li = todoLi(world, title);
  if (!li) throw new Error('no todo with title "' + title + '"');
  li.querySelector('label').dispatchEvent(new world.window.Event('dblclick', { bubbles: true }));
}
function editingInput(world) {
  return world.document.querySelector('.todo-list li.editing .edit');
}

// Capture the current <li> for a title so a later step can assert the node survived the
// interaction in place. This is verification support: it asserts nothing about production, it
// only records the node a scenario holds before the change. It carries no production plank.
Given('the list item for {string} is captured', function (title) {
  var li = todoLi(this, title);
  if (!li) throw new Error('no todo with title "' + title + '" to capture');
  this.capturedNodes = this.capturedNodes || {};
  this.capturedNodes[title] = li;
});

// Assert the node captured before the change is the same node still attached to the list after
// the change. Production MUST mutate the list item in place rather than rebuild the list, so if
// the app detached and recreated the <li> the captured reference is no longer the current node.
Then('the list item for {string} is the captured node', function (title) {
  var captured = this.capturedNodes && this.capturedNodes[title];
  if (!captured) throw new Error('no captured node for "' + title + '"');
  var current = todoLi(this, title);
  if (!current) throw new Error('todo "' + title + '" is no longer in the list after the change');
  if (captured !== current)
    throw new Error('list item for "' + title + '" was rebuilt, not mutated in place');
  if (!captured.parentNode || !captured.parentNode.classList.contains('todo-list'))
    throw new Error('captured list item for "' + title + '" is no longer attached to the todo list');
});

// ---- given: starting state --------------------------------------------------

Given('the app has no todos', function () {
  var n = todoLis(this).length;
  if (n !== 0) throw new Error('expected no todos, found ' + n);
});

Given('the app has the todo {string}', function (title) {
  addTodoViaUI(this, title);
});
Given('the app has the active todo {string}', function (title) {
  addTodoViaUI(this, title);
});
Given('the app has the completed todo {string}', function (title) {
  addTodoViaUI(this, title);
  checkTodoByTitle(this, title, true);
});
Given('the app has {int} active todos', function (count) {
  for (var i = 1; i <= count; i++) addTodoViaUI(this, 'Active todo ' + i);
});

// Direct localStorage setup: seed the persisted record without going through the UI.
// These are preconditions for reload/persistence scenarios, so they use verification support
// alone and carry no production plank.
Given('localStorage holds the todo {string}', function (title) {
  setStoredTodo(this.window, title, false);
});
Given('localStorage holds the completed todo {string}', function (title) {
  setStoredTodo(this.window, title, true);
});
Given('localStorage holds the active todo {string}', function (title) {
